  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Calculates the final price for a booking after applying any eligible discount.
   * Algorithm:
   *   if customer == null OR bookingTime == null then return price
   *   if customer.membershipPackage == null then return price
   *   if not customer.membershipPackage.hasAward(Award.DISCOUNTS) then return price
   *   // Check if booking is at least 24 hours before departure
   *   if (departureTime - bookingTime) >= 24 hours then:
   *     discountedPrice = price * 0.8
   *     return Math.round(discountedPrice * 10) / 10.0  // keep one decimal
   *   else return price
   * Related Features: price, departureTime, customer.membershipPackage.hasAward()
   * Related Classes: Customer, MembershipPackage, Award
   * Input: customer : Customer, bookingTime : String - ISO datetime format
   * Output: double - final price with one decimal place
   * Pre-condition: none
   * Post-condition: none
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public double calculateDiscountedPrice(final Customer customer, final String bookingTime)
  {
    if (customer == null || bookingTime == null)
    {
      return getPrice();
    }
    if (customer.getMembershipPackage() == null)
    {
      return getPrice();
    }
    if (!customer.getMembershipPackage().hasAward(Award.DISCOUNTS))
    {
      return getPrice();
    }
    // Check if booking is at least 24 hours before departure
    if (getDepartureTime().compareTo(bookingTime) >= 24 * 60 * 60 * 1000)
    {
      double discountedPrice = getPrice() * 0.8;
      return Math.round(discountedPrice * 10) / 10.0;
    }
    else
    {
      return getPrice();
    }
  }

  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Calculates the total reward points a customer earns from this trip for a given month. Only customers whose membership package contains the POINTS award are eligible. Only bookings whose booking date falls inside the requested month are counted. Each booked seat contributes 5 points. Invalid inputs, missing membership packages, or unsupported rewards return 0.
   * Algorithm:
   *   if customer == null OR currentMonth == null then return 0
   *   if customer.membershipPackage == null then return 0
   *   if not customer.membershipPackage.hasAward(Award.POINTS) then return 0
   *   totalPoints = 0
   *   for each booking in this.bookings:
   *     if booking.customer == customer AND booking.isInMonth(currentMonth) then:
   *       totalPoints += booking.numberOfSeats * 5
   *   return totalPoints
   * Related Features: bookings, customer, membershipPackage, hasAward()
   * Related Classes: Customer, MembershipPackage, Award, Booking
   * Input: customer : Customer, currentMonth : String - format "YYYY-MM"
   * Output: int - total points (0 if ineligible)
   * Pre-condition: none
   * Post-condition: none
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public int calculateMonthlyPoints(final Customer customer, final String currentMonth)
  {
    if (customer == null || currentMonth == null)
    {
      return 0;
    }
    if (customer.getMembershipPackage() == null)
    {
      return 0;
    }
    if (!customer.getMembershipPackage().hasAward(Award.POINTS))
    {
      return 0;
    }
    int totalPoints = 0;
    for (Booking booking : getBookings())
    {
      if (booking.getCustomer() == customer && booking.isInMonth(currentMonth))
      {
        totalPoints += booking.getNumberOfSeats() * 5;
      }
    }
    return totalPoints;
  }

